def investigate(context, acquire):
    history = acquire("history")
    actions = context.get("actions", [])
    goal = context.get("goal")

    def simulate(seq):
        committed = {}
        pending = {}
        in_tx = False
        tx_conn = None
        for act in seq:
            op = act.get("op")
            conn = act.get("connection", "main")
            key = act.get("key")
            val = act.get("value")
            if op == "begin":
                in_tx = True
                tx_conn = conn
                pending = {}
            elif op == "commit":
                if in_tx and conn == tx_conn:
                    for k, v in pending.items():
                        if v is None:
                            committed.pop(k, None)
                        else:
                            committed[k] = v
                in_tx = False
                tx_conn = None
                pending = {}
            elif op == "rollback":
                in_tx = False
                tx_conn = None
                pending = {}
            elif op == "put":
                if in_tx and conn == tx_conn:
                    pending[key] = val
                else:
                    committed[key] = val
            elif op == "update":
                if in_tx and conn == tx_conn:
                    if key in committed or key in pending:
                        pending[key] = val
                else:
                    if key in committed:
                        committed[key] = val
            elif op == "delete":
                if in_tx and conn == tx_conn:
                    pending[key] = None
                else:
                    committed.pop(key, None)
        return committed

    committed = simulate(actions)
    if goal == "committed_count":
        return {"value": len(committed), "unresolved": False}
    if goal == "committed_sum":
        return {"value": sum(committed.values()), "unresolved": False}
    if goal == "channel":
        return {"value": None, "unresolved": True}
    return {"value": None, "unresolved": True}

